namespace ReservationService.DTOs.Reservations;

/// <summary>
/// Public API response representation of a Reservation.
/// Decouples internal database entities from external clients.
/// Includes computed and generated values like 'Nights', 'ReservationCode', and an optional 'Message'.
/// </summary>
public class ReservationResponseDto
{
    // Friendly status or outcome message (e.g. "Reservation created successfully") matching LLD sample
    public string Message { get; set; } = string.Empty;

    public int ReservationId { get; set; }

    // Human-readable booking reference generated by backend (e.g. "RES-20261119-ABCD")
    public string ReservationCode { get; set; } = string.Empty;

    public int GuestId { get; set; }

    public int RoomId { get; set; }

    public int Adults { get; set; }

    public int Children { get; set; }

    public DateOnly CheckIn { get; set; }

    public DateOnly CheckOut { get; set; }

    // Calculated on the backend: CheckOut.DayNumber - CheckIn.DayNumber
    public int Nights { get; set; }

    // Reservation lifecycle status (e.g. "Confirmed")
    public string Status { get; set; } = string.Empty;
}
